/**
 * AUTO-GENERATED regression lock over the reviewed corpus - DO NOT EDIT.
 * 6490 locked cases across 92 manifests.
 * Regenerate after intentional engine changes:
 *   node tools/generate_corpus_tests.mjs
 *
 * Lock policy:
 *  - exact: time, space, and confidence are pinned. Any drift fails.
 *  - abstain: the engine must keep abstaining or answer with the
 *    labeled profile; asserting a DIFFERENT bound fails (soundness).
 */
import assert from "node:assert/strict";
import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import test, { describe } from "node:test";
import { analyseCppFunctionsInDocument } from "../src/index.js";
import { equivalent } from "./helpers/bound-equivalence.js";

const clangPath = process.env.PROJECT_X_CLANG ?? "C:\\Program Files\\LLVM\\bin\\clang++.exe";
const datasetsDir = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "datasets");
const clangAvailable = existsSync(clangPath);

function profileMatches(actual, label) {
  return actual.worstCaseTime === label.time && actual.auxiliarySpace === label.space;
}

describe("corpus lock: cf-batch-01.manifest.json", { skip: !clangAvailable }, () => {
  process.env.PROJECT_X_CLANG = clangPath;
  const cases = [{"kind":"exact","id":"cf-batch-01","symbol":"solve","time":"O(n log n)","space":"O(n)","confidence":"exact"}];
  const results = new Map<string, import("../src/model.js").AnalysisResult>();
  test("setup: parse cf-batch-01.cpp", () => {
    const source = readFileSync(join(datasetsDir, "cf-batch-01.cpp"), "utf8");
    const analysis = analyseCppFunctionsInDocument(source, cases.map((c) => c.symbol));
    for (const [symbol, value] of analysis) results.set(symbol, value);
    assert.equal(analysis.size > 0 || cases.length === 0, true);
  });
  test("cf-batch-01", () => {
    const actual = results.get("solve")!;
    assert.ok(equivalent(actual.worstCaseTime, "O(n log n)"), "time drift");
    assert.ok(equivalent(actual.auxiliarySpace, "O(n)"), "space drift");
    assert.equal(actual.confidence, "exact");
  });
});

