  const results = new Map<string, import("../src/model.js").AnalysisResult>();
  test("setup: parse cpp-axis-stl-14.cpp", () => {
    const source = readFileSync(join(datasetsDir, "cpp-axis-stl-14.cpp"), "utf8");
    const analysis = analyseCppFunctionsInDocument(source, cases.map((c) => c.symbol));
    for (const [symbol, value] of analysis) results.set(symbol, value);
    assert.equal(analysis.size > 0 || cases.length === 0, true);
  });
